 function autoCalc(){const s=service.value,q=$('dm-quality'),cs=$('dm-csat'),prod=$('dm-prod');if(!q||!cs||!prod)return;
  const clamp=v=>Math.max(0,Math.min(100,v)),num=id=>Math.max(0,Number($(id)?.value||0)),res=$('work-result')?.value,typ=$('work-type')?.value;
  if(s==='quality'){
   const samples=Math.max(1,num('dm-samples')),critical=num('dm-critical');
   const criticalRate=Math.min(1,critical/samples);
   const resultScore=res==='critical'?0:res==='observation'?80:100;
   const compliance=clamp(100-criticalRate*100);
   q.value=clamp(compliance*.70+resultScore*.30).toFixed(1);
   cs.value=q.value;
   prod.value=samples;
  }else if(s==='tickets'){
   const closed=num('dm-closed'),open=num('dm-open'),total=closed+open,sla=clamp(num('dm-sla'));
   const closure=total?closed/total*100:0,caseSla=typ==='yes'?100:typ==='no'?0:sla;
   q.value=clamp(sla*.60+closure*.25+caseSla*.15).toFixed(1);
   cs.value=clamp(sla*.70+closure*.30).toFixed(1);
   prod.value=closed;
  }else{
   const calls=num('dm-survey-calls'),responses=num('dm-responses'),entered=clamp(num('dm-response-rate'));
   const responseRate=calls?clamp(responses/calls*100):entered;
   const outcome=res==='responded'?100:res==='refused'?35:0;
   q.value=clamp(responseRate*.70+outcome*.30).toFixed(1);
   cs.value=clamp(responseRate*.40+outcome*.60).toFixed(1);
   prod.value=calls;
   if($('dm-response-rate'))$('dm-response-rate').value=responseRate.toFixed(1);
  }
 } ['dm-samples','dm-critical','dm-closed','dm-open','dm-sla','dm-survey-calls','dm-responses','dm-response-rate'].forEach(id=>$(id)?.addEventListener('input',autoCalc));service.addEventListener('change',()=>{details();setTimeout(autoCalc,0)});$('emp-work-details')?.addEventListener('change',autoCalc);
